// REQUIRES: linux

// Element types that can't be mapped onto ext_vector_type (e.g. bfloat16) use
// an element-wise fallback for sycl::vec operators. This test checks how that
// fallback accesses operands that live in memory: element-by-element accesses
// to the operand's memory prevent vector loads in the backend.

#include <sycl/sycl.hpp>

using bf16 = sycl::ext::oneapi::bfloat16;
using vec_t = sycl::vec<bf16, 8>;

